import{_ as a,o as t,c as d,ag as o}from"./chunks/framework.gmyryY1Z.js";const u=JSON.parse('{"title":"アプリ概要","description":"","frontmatter":{},"headers":[],"relativePath":"ja/apps/index.md","filePath":"ja/apps/index.md","lastUpdated":null}'),i={name:"ja/apps/index.md"};function n(r,e,l,s,c,h){return t(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="アプリ概要" tabindex="-1">アプリ概要 <a class="header-anchor" href="#アプリ概要" aria-label="Permalink to &quot;アプリ概要&quot;">​</a></h1><p>Fast Vue3 には 5 つの独立した UI エコシステムアプリが含まれています。</p><h2 id="アプリ一覧" tabindex="-1">アプリ一覧 <a class="header-anchor" href="#アプリ一覧" aria-label="Permalink to &quot;アプリ一覧&quot;">​</a></h2><table tabindex="0"><thead><tr><th>アプリ</th><th>UI フレームワーク</th><th>ポート</th><th>コマンド</th></tr></thead><tbody><tr><td>web-antd</td><td>Ant Design Vue 4.x</td><td>3001</td><td><code>pnpm dev:antd</code></td></tr><tr><td>web-ele</td><td>Element Plus 2.x</td><td>3002</td><td><code>pnpm dev:ele</code></td></tr><tr><td>web-naive</td><td>Naive UI 2.x</td><td>3003</td><td><code>pnpm dev:naive</code></td></tr><tr><td>web-arco</td><td>Arco Design Vue 2.x</td><td>3004</td><td><code>pnpm dev:arco</code></td></tr><tr><td>web-tdesign</td><td>TDesign Vue Next 1.x</td><td>3005</td><td><code>pnpm dev:tdesign</code></td></tr></tbody></table><h2 id="共通機能" tabindex="-1">共通機能 <a class="header-anchor" href="#共通機能" aria-label="Permalink to &quot;共通機能&quot;">​</a></h2><h3 id="認証フロー" tabindex="-1">認証フロー <a class="header-anchor" href="#認証フロー" aria-label="Permalink to &quot;認証フロー&quot;">​</a></h3><ol><li>未認証ユーザー → <code>/login</code> に自動リダイレクト</li><li>ログイン成功 → ユーザー情報取得 → メインレイアウトへ</li><li>ログアウト → トークンクリア → <code>/login</code> にリダイレクト</li></ol><h3 id="メインレイアウト" tabindex="-1">メインレイアウト <a class="header-anchor" href="#メインレイアウト" aria-label="Permalink to &quot;メインレイアウト&quot;">​</a></h3><ul><li>折りたたみ可能なサイドバーナビゲーション</li><li>トップヘッダー（ユーザー情報・ログアウト）</li><li>コンテンツエリア（<code>&lt;RouterView /&gt;</code>）</li></ul><h3 id="ファイルベースルーティング" tabindex="-1">ファイルベースルーティング <a class="header-anchor" href="#ファイルベースルーティング" aria-label="Permalink to &quot;ファイルベースルーティング&quot;">​</a></h3><p><code>unplugin-vue-router</code> により <code>src/views/</code> 以下の <code>.vue</code> ファイルが自動でルートに登録されます。</p><h3 id="mock-データ" tabindex="-1">Mock データ <a class="header-anchor" href="#mock-データ" aria-label="Permalink to &quot;Mock データ&quot;">​</a></h3><p>各アプリの <code>mock/</code> ディレクトリ：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/user/login    → { token: &#39;mock-token-xxx&#39; }</span></span>
<span class="line"><span>GET  /api/user/profile  → { userName, avatar, role }</span></span>
<span class="line"><span>POST /api/user/logout   → {}</span></span></code></pre></div><h2 id="ui-の分離" tabindex="-1">UI の分離 <a class="header-anchor" href="#ui-の分離" aria-label="Permalink to &quot;UI の分離&quot;">​</a></h2><p>異なるフレームワークのコンポーネントは互いに干渉しません。各アプリの <code>vite.config.ts</code> に渡された resolver が自動インポートのスコープを制御します。</p><h2 id="新しい-ui-エコシステムの追加" tabindex="-1">新しい UI エコシステムの追加 <a class="header-anchor" href="#新しい-ui-エコシステムの追加" aria-label="Permalink to &quot;新しい UI エコシステムの追加&quot;">​</a></h2><p><a href="./add-new">新しい UI ライブラリの追加</a> を参照してください。</p>`,18)])])}const b=a(i,[["render",n]]);export{u as __pageData,b as default};
